const n={loading:n=>{const{normalize:r}=n;return r(["লোড হচ্ছে"])},Ranking:n=>{const{normalize:r}=n;return r(["র‍্যাংকিং"])},Daily:n=>{const{normalize:r}=n;return r(["দৈনিক"])},Weekly:n=>{const{normalize:r}=n;return r(["সাপ্তাহিক"])},Monthly:n=>{const{normalize:r}=n;return r(["মাসিক"])},Duration:n=>{const{normalize:r,interpolate:t,named:o}=n;return r(["সময়কাল ",t(o("duration"))])},OnlyShowTop:n=>{const{normalize:r,interpolate:t,named:o}=n;return r(["র‍্যাঙ্কিংয়ের তালিকা শুধুমাত্র উপরের ",t(o("num"))," দেখায়"])},i_got_it:n=>{const{normalize:r}=n;return r(["বুঝে পান"])},levelCount:n=>{const{normalize:r,interpolate:t,named:o}=n;return r(["Lv.",t(o("count"))])},honor:n=>{const{normalize:r}=n;return r(["সম্মান"])},charm:n=>{const{normalize:r}=n;return r(["যাদু"])},room:n=>{const{normalize:r}=n;return r(["রুম"])},honor_tip:n=>{const{normalize:r}=n;return r(["সম্মানসূচক র‍্যাঙ্কিং আপনার পাঠানো কয়েনের সংখ্যা দ্বারা নির্ধারিত হয়, লাকি গিফট কয়েনের মূল্যের মাত্র ২০% গণনা করে।"])},charm_tip:n=>{const{normalize:r}=n;return r(["চার্ম র‍্যাঙ্কিং আপনার পাওয়া ডায়মন্ডের সংখ্যা দ্বারা নির্ধারিত হয়, লাকি গিফট ডায়মন্ডের মূল্যের মাত্র ২০% গণনা করে।"])},room_tip:n=>{const{normalize:r}=n;return r(["রুম র‍্যাঙ্কিং রুমে প্রাপ্ত কয়েনের সংখ্যা দ্বারা নির্ধারিত হয়, লাকি গিফট কয়েনের মূল্যের মাত্র ২০% গণনা করে।"])},viewLimit:n=>{const{normalize:r}=n;return r(["শুধুমাত্র লেভেল 10 বা তার উপরে দেখতে পারবেন।"])},statementLang:n=>{const{normalize:r}=n;return r(["এই ইভেন্টটি Google Play-এর সাথে অনুমোদিত নয়। এই অ্যাপের সর্বস্বত্ব সংরক্ষিত।"])},statementIosLang:n=>{const{normalize:r}=n;return r(["এই ইভেন্টটি Apple Inc.-এর সাথে সম্পর্কিত নয়। এই অ্যাপের সর্বস্বত্ব সংরক্ষিত।"])}};export{n as default};
